@startuml

enum Color {
  WHITE
  BLACK
}

enum ActionCardType {
  ROLL_DIE_EXTRA_TURN
  CONNECT_ADJACENT_TILES
  REMOVE_CONNECTION_PIECE
  MOVE_TO_ARBITRARY_TILE
  LOSE_NEXT_TURN
}

class TileO {}

class Game {
  + spareConnectionPieces : int = 32
  + numberOfActionCards : int = 32
}

class Connection {}

class Die {}

class Deck {}

class ActionCard {
  + instructions : string
}

abstract class Tile {
  + color : Color
}

class HiddenTile extends Tile {}

class ActionTile extends Tile {
  + inactivityPeriod : int
  + turnsUntilActive : int
}

class NormalTile extends Tile {}

class Player {
  + number : int
  + color : Color
}

TileO "1" -- "1" Game
Game "1" *-- "* Tile"
Game "1" *-- "* Connection"
Game "1" *-- "1" Die
Game "1" *-- "1" Deck
Game "1" --> "0..1 currentPlayer" Player
Game "1" *-- "2..4" Player
Deck "1" *-- "32" ActionCard
Tile "1" -- "0..4" Connection
Player "1" --> "1" Tile : startingPosition
Player "1" --> "1" Tile : currentTile
Player "1" --> "0..1" ActionCard : takes

@enduml

